class Solution:
    def searchInsert(self, nums: list[int], target: int) -> int:
        lo, hi = 0, len(nums) - 1
        while lo <= hi:
            mid = (lo + hi) // 2
            if nums[mid] == target:  # viz:check
                return mid  # viz:found
            if nums[mid] < target:
                lo = mid + 1  # viz:go_right
            else:
                hi = mid - 1  # viz:go_left
        return lo  # viz:insert
